insert into books (id, school_id, judul, penulis, penerbit, tahun, isbn, category_id, shelf_id, cover_url, deskripsi) values
  (1, 1, 'Si Kancil dan Buaya', 'Tim Dongeng Nusantara', 'Pustaka Ceria', 2021, NULL, 6, 4, '/covers/demo/buku-01.svg', 'Kancil yang cerdik ingin menyeberang sungai penuh buaya. Dengan akal cerdasnya, ia meminta para buaya berbaris untuk dihitung.'),
  (2, 1, 'Malin Kundang', 'Tim Dongeng Nusantara', 'Pustaka Ceria', 2020, NULL, 6, 4, '/covers/demo/buku-02.svg', 'Kisah anak yang merantau lalu lupa pada ibunya. Cerita rakyat Sumatra Barat tentang pentingnya berbakti kepada orang tua.'),
  (3, 1, 'Timun Mas', 'Tim Dongeng Nusantara', 'Pustaka Ceria', 2022, NULL, 6, 4, '/covers/demo/buku-03.svg', 'Timun Mas berlari dari raksasa dengan bekal ajaib dari seorang pertapa: biji mentimun, jarum, garam, dan terasi.'),
  (4, 1, 'Layang-Layang Merah Dinda', 'Rara Anindita', 'Kancil Kecil', 2023, NULL, 1, 1, '/covers/demo/buku-04.svg', 'Dinda membuat layang-layang sendiri untuk lomba di kampung. Saat talinya putus, ia belajar tentang pantang menyerah.'),
  (5, 1, 'Sepeda Baru Bima', 'Andi Prasetyo', 'Kancil Kecil', 2022, NULL, 1, 1, '/covers/demo/buku-05.svg', 'Bima menabung berbulan-bulan demi sepeda impian. Tapi temannya sedang butuh bantuan, dan Bima harus memilih.'),
  (6, 1, 'Kue Lapis untuk Nenek', 'Sari Wulandari', 'Rumah Dongeng', 2021, NULL, 1, 1, '/covers/demo/buku-06.svg', 'Bersama ibunya, Ayu belajar membuat kue lapis untuk ulang tahun nenek. Lapis demi lapis, penuh kesabaran dan cinta.'),
  (7, 1, 'Petualangan di Pulau Pelangi', 'Kirana Dewi', 'Bintang Kecil', 2023, NULL, 3, 5, '/covers/demo/buku-07.svg', 'Tiga sahabat terdampar di pulau yang warnanya berubah setiap jam. Mereka harus menemukan jalan pulang sebelum senja.'),
  (8, 1, 'Robot Kecil Bernama Tiko', 'Bayu Saputra', 'Bintang Kecil', 2024, NULL, 3, 5, '/covers/demo/buku-08.svg', 'Tiko adalah robot pembersih yang ingin punya teman. Ia menjelajahi kota dan menemukan arti persahabatan.'),
  (9, 1, 'Rahasia Pohon Beringin', 'Kirana Dewi', 'Bintang Kecil', 2022, NULL, 3, 5, '/covers/demo/buku-09.svg', 'Di bawah pohon beringin tua di halaman sekolah, Rani menemukan peta rahasia yang ditulis murid puluhan tahun lalu.'),
  (10, 1, 'Geng Pesut Mahakam', 'Studio Borneo Ceria', 'Komik Kita', 2024, NULL, 4, 5, '/covers/demo/buku-10.svg', 'Pesut-pesut Sungai Mahakam bekerja sama menjaga sungai tetap bersih dari sampah. Komik lucu tentang cinta lingkungan.'),
  (11, 1, 'Si Beruang Madu Penjaga Hutan', 'Studio Borneo Ceria', 'Komik Kita', 2023, NULL, 4, 5, '/covers/demo/buku-11.svg', 'Beruang madu kecil bernama Maru menjaga hutan Kalimantan dari penebang liar bersama teman-teman satwanya.'),
  (12, 1, 'Kapten Kucing Balikpapan', 'Raka Mahendra', 'Komik Kita', 2024, NULL, 4, 5, '/covers/demo/buku-12.svg', 'Kapten Kucing berpatroli di pelabuhan Balikpapan. Setiap hari ada misteri baru yang harus dipecahkan.'),
  (13, 1, 'Mengenal Planet Tata Surya', 'Dr. Laras Pertiwi', 'Sains Anak', 2022, NULL, 2, 3, '/covers/demo/buku-13.svg', 'Ajak anak berkeliling tata surya: dari Merkurius yang panas sampai Neptunus yang dingin, lengkap dengan fakta seru.'),
  (14, 1, 'Ensiklopedia Hewan Kalimantan', 'Tim Sains Anak', 'Sains Anak', 2021, NULL, 2, 3, '/covers/demo/buku-14.svg', 'Kenali orangutan, bekantan, rangkong, dan hewan unik lain dari hutan Kalimantan beserta cara melindunginya.'),
  (15, 1, 'Kenapa Hujan Turun?', 'Dr. Laras Pertiwi', 'Sains Anak', 2023, NULL, 2, 3, '/covers/demo/buku-15.svg', 'Perjalanan setetes air dari laut ke awan lalu kembali ke bumi. Penjelasan siklus air yang mudah dan penuh gambar.'),
  (16, 1, 'Asyik Belajar Perkalian', 'Budi Hartono, S.Pd.', 'Pena Pintar', 2024, NULL, 5, 2, '/covers/demo/buku-16.svg', 'Belajar perkalian 1 sampai 10 lewat permainan, lagu, dan teka-teki. Cocok untuk latihan di rumah.'),
  (17, 1, 'Bahasa Indonesia Ceria Kelas 3', 'Tim Pena Pintar', 'Pena Pintar', 2024, NULL, 5, 2, '/covers/demo/buku-17.svg', 'Latihan membaca, menulis, dan bercerita untuk kelas 3 dengan teks-teks pendek yang dekat dengan kehidupan anak.'),
  (18, 1, 'IPAS Seru Kelas 4', 'Tim Pena Pintar', 'Pena Pintar', 2024, NULL, 5, 2, '/covers/demo/buku-18.svg', 'Percobaan sederhana dan pengamatan lingkungan sekitar untuk memahami materi IPAS kelas 4.'),
  (19, 1, 'Kisah Teladan Para Nabi', 'Ust. Hasan Basri', 'Cahaya Iman', 2020, NULL, 7, 3, '/covers/demo/buku-19.svg', 'Kumpulan kisah teladan para nabi yang ditulis dengan bahasa sederhana untuk anak sekolah dasar.'),
  (20, 1, 'Doa Sehari-hari Anak', 'Ust. Hasan Basri', 'Cahaya Iman', 2021, NULL, 7, 3, '/covers/demo/buku-20.svg', 'Doa-doa pendek untuk kegiatan sehari-hari, dari bangun tidur sampai belajar, lengkap dengan artinya.'),
  (21, 1, 'Indahnya Berbagi', 'Nur Aisyah', 'Cahaya Iman', 2022, NULL, 7, 1, '/covers/demo/buku-21.svg', 'Cerita-cerita pendek tentang anak-anak yang belajar berbagi dengan teman, tetangga, dan sesama.'),
  (22, 1, 'Origami Hewan Lucu', 'Mei Lestari', 'Kreasi Anak', 2023, NULL, 8, 3, '/covers/demo/buku-22.svg', 'Langkah demi langkah melipat kertas menjadi burung, katak, kucing, dan hewan lucu lainnya.'),
  (23, 1, 'Menggambar Itu Mudah', 'Dimas Aryo', 'Kreasi Anak', 2022, NULL, 8, 3, '/covers/demo/buku-23.svg', 'Mulai dari bentuk dasar, anak diajak menggambar hewan, rumah, dan pemandangan dengan percaya diri.'),
  (24, 1, 'Berkebun di Rumah', 'Mei Lestari', 'Kreasi Anak', 2024, NULL, 8, 3, '/covers/demo/buku-24.svg', 'Menanam cabai, tomat, dan kangkung di pot kecil. Panduan berkebun sederhana untuk anak dan keluarga.');
