-- Sinkronkan penghitung ID setelah insert dengan ID manual
select setval(pg_get_serial_sequence('schools','id'),     (select max(id) from schools));
select setval(pg_get_serial_sequence('categories','id'),  (select max(id) from categories));
select setval(pg_get_serial_sequence('shelves','id'),     (select max(id) from shelves));
select setval(pg_get_serial_sequence('books','id'),       (select max(id) from books));
select setval(pg_get_serial_sequence('book_copies','id'), (select max(id) from book_copies));
select setval(pg_get_serial_sequence('students','id'),    (select max(id) from students));
select setval(pg_get_serial_sequence('loans','id'),       (select max(id) from loans));

-- ---------- Nomor stiker terpisah dari isi QR ----------
-- Di data contoh, kode DEMO-xxxx menjadi NOMOR STIKER, dan tiap eksemplar mendapat isi QR acak sendiri.
update book_copies
   set label = qr_code,
       qr_code = 'SP' || upper(replace(substr(gen_random_uuid()::text, 1, 13), '-', ''))
 where label is null;

-- ikon kategori demo
update categories set icon = case kode when '01' then 'kategori/cerpen' when '02' then 'kategori/pengetahuan' when '03' then 'kategori/fiksi' when '04' then 'kategori/komik' when '05' then 'kategori/pelajaran' when '06' then 'kategori/cerita-rakyat' when '07' then 'kategori/agama' when '08' then 'kategori/hobi' else 'kategori/semua' end where icon is null;
